import torch
from torch.utils.data import Dataset
import numpy as np
import os
import cv2

class SaltDataset(Dataset):
    def __init__(self, df, img_dir, mask_dir=None, transform=None, is_test=False):
        self.df = df
        self.img_dir = img_dir
        self.mask_dir = mask_dir
        self.transform = transform
        self.is_test = is_test

    def __len__(self):
        return len(self.df)

    def __getitem__(self, idx):
        img_id = self.df.iloc[idx]['id']
        img_path = os.path.join(self.img_dir, "images", f"{img_id}.png")
        img = cv2.imread(img_path, cv2.IMREAD_GRAYSCALE)
        img = cv2.cvtColor(img, cv2.COLOR_GRAY2RGB)

        if self.is_test:
            if self.transform:
                augmented = self.transform(image=img)
                img = augmented['image']
            return img, img_id

        if self.mask_dir:
            mask_path = os.path.join(self.mask_dir, f"{img_id}.png")
            mask = cv2.imread(mask_path, cv2.IMREAD_GRAYSCALE)
            if mask is None: 
                mask = np.zeros((101, 101), dtype=np.uint8)
            mask = mask / 255.0
        else:
            mask = np.zeros((101, 101), dtype=np.float32)

        if self.transform:
            augmented = self.transform(image=img, mask=mask)
            img = augmented['image']
            mask = augmented['mask']

        # Ensure mask has correct shape (1, H, W)
        if len(mask.shape) == 2:
            mask = np.expand_dims(mask, axis=0)
        elif mask.shape[0] != 1:
            mask = np.expand_dims(mask, axis=0)

        return img, torch.from_numpy(mask).float()

